children.text:
@font-face {
    font-family: 'Liberation Mono';
    src: url('../font/LiberationMono-Bold.ttf') format('truetype');
    font-weight: bold;
    font-style: normal;
}

body {
    font-family: 'Liberation Mono', 'Courier New', monospace;
    font-size: 14px;
    font-weight: bold;
    line-height: 1.4;
    margin: 20px;
    background-color: white;
    color: black;
}

.test-container {
    max-width: 700px;
    padding: 20px;
    border: 2px solid #555;
}

.terminal-block {
    background-color: #000;
    color: #0f0;
    padding: 15px;
    border-radius: 5px;
    margin: 10px 0;
}

.data-table {
    white-space: pre;
    font-size: 12px;
    border: 1px solid #999;
    padding: 10px;
    margin: 10px 0;
}
